//! How a host's added nodes are spelled in one state value, and read back.
//!
//! One key holds the whole list (`NodeKey::Added`), the same reasoning as the
//! link edits: adding a node is then one store write and one undo step. Each
//! entry is `idname/name/x,y`, joined by `;`.
//!
//! The separators are characters the fields do not contain. An `idname` is a
//! registered C string; a position is two floats; and an added node's NAME is
//! generated by phiber (the type's label plus a unique suffix), so it is made
//! without `/` or `;` rather than carrying arbitrary user text the way a file
//! node's name can. An entry that does not parse is dropped rather than guessed
//! at — a half-read node would draw sockets to nowhere.

use super::BNodeAddition;

const FIELD: char = '/';
const NEXT: char = ';';
const COMMA: char = ',';

/// `idname/name/x,y;…` — every added node, in order.
pub fn encode(adds: &[BNodeAddition]) -> String {
    let mut out = String::new();
    for a in adds {
        if !out.is_empty() {
            out.push(NEXT);
        }
        out.push_str(&a.idname);
        out.push(FIELD);
        out.push_str(&a.name);
        out.push(FIELD);
        out.push_str(&a.at.0.to_string());
        out.push(COMMA);
        out.push_str(&a.at.1.to_string());
    }
    out
}

/// The added nodes back out of the store.
pub fn decode(text: &str) -> Vec<BNodeAddition> {
    let mut out = Vec::new();
    for entry in text.split(NEXT).filter(|e| !e.is_empty()) {
        let mut parts = entry.splitn(3, FIELD);
        let (Some(idname), Some(name), Some(pos)) = (parts.next(), parts.next(), parts.next()) else {
            continue;
        };
        let Some((x, y)) = pos.split_once(COMMA) else { continue };
        let (Ok(x), Ok(y)) = (x.trim().parse::<f32>(), y.trim().parse::<f32>()) else { continue };
        if idname.is_empty() || name.is_empty() {
            continue;
        }
        out.push(BNodeAddition { idname: idname.into(), name: name.into(), at: (x, y) });
    }
    out
}

/// This host's added nodes, out of the store.
pub fn additions_of(state: &crate::v2::state::BState, host: crate::v2::host::BHostType) -> super::BNodeAdditions {
    use crate::v2::state::{BKey as _, NodeKey};
    super::BNodeAdditions { added: decode(state.get(&NodeKey::Added(host).path()).unwrap_or("")) }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn adds() -> Vec<BNodeAddition> {
        vec![
            BNodeAddition { idname: "ShaderNodeEmission".into(), name: "Emission".into(), at: (1.5, -2.0) },
            BNodeAddition { idname: "ShaderNodeMath".into(), name: "Math.001".into(), at: (0.0, 40.0) },
        ]
    }

    #[test]
    fn the_additions_survive_a_round_trip_through_the_store() {
        assert_eq!(decode(&encode(&adds())), adds());
    }

    #[test]
    fn nothing_stored_is_no_additions() {
        assert_eq!(decode(""), Vec::new());
        assert_eq!(encode(&[]), "");
    }

    #[test]
    fn a_half_written_entry_is_dropped_rather_than_guessed_at() {
        for bad in ["ShaderNodeMath", "ShaderNodeMath/Math", "ShaderNodeMath/Math/nope", "/Math/0,0", "ShaderNodeMath//0,0"] {
            assert_eq!(decode(bad), Vec::new(), "{bad:?} should not have parsed");
        }
        // A bad entry does not take its neighbours with it.
        let mixed = format!("broken;{}", encode(&adds()[..1]));
        assert_eq!(decode(&mixed).len(), 1, "the good entry survives");
    }

    #[test]
    fn a_position_with_a_negative_and_a_decimal_survives() {
        let round = decode(&encode(&adds()));
        assert_eq!(round[0].at, (1.5, -2.0));
    }
}
